css:
/* ============================================================
   LIFE ERP — Knowledge Centre
   ERPNext-ready full stylesheet

   18-Aug-2026 UI update:
   - Compact 245px desktop sidebar by default
   - 322px sidebar while search is focused/active
   - Sidebar section count badges removed

   This version intentionally uses:
   - No CSS custom-property references
   - No forced-priority declarations
   - Literal colours, fonts, radii, shadows and dimensions
   ============================================================ */

/* ============================================================
   ERPNext / Frappe host-page compatibility
   Added for the custom Web Page version.
   ============================================================ */
html body.life-kc-erpnext-page {
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}
html body.life-kc-erpnext-page .navbar,
html body.life-kc-erpnext-page .web-footer,
html body.life-kc-erpnext-page footer.web-footer {
  display: none;
}
.life-kc-root {
  position: relative;
  width: 100vw;
  min-height: 100vh;
  margin-left: calc(50% - 50vw);
  isolation: isolate;
}
/* Keep Bootstrap/Frappe button styling from overriding Knowledge Centre buttons. */
.life-kc-root .btn {
  text-shadow: none;
}

/* ============================================================
   LIFE ERP — Knowledge Centre
   Dual-tone design system.
   PRIMARY family  : deep forest green  (navigation, headers, accents)
   SUPPORTING family: soft sage tints   (card bodies, panels, tables)
   Semantic colours are fixed in meaning across every screen.
   ============================================================ */
.life-kc-root, .life-kc-root *{box-sizing:border-box;margin:0;padding:0}
.life-kc-root{scroll-behavior:smooth;-webkit-text-size-adjust:100%;overflow-x:hidden}
.life-kc-root{font-family:Georgia,"Iowan Old Style","Times New Roman",serif;background:#F6F8F6;color:#33443B;
 font-size:clamp(16.5px,.55vw + 15px,18px);line-height:1.66;-webkit-font-smoothing:antialiased;overflow-x:hidden}
.life-kc-root a{color:#1E5631;text-decoration:none}
.life-kc-root a:hover{text-decoration:underline}
.life-kc-root :focus-visible{outline:2.5px solid #7FB63A;outline-offset:3px;border-radius:3px}
@media (prefers-reduced-motion:reduce){.life-kc-root, .life-kc-root *{animation:none;transition:none}}
.life-kc-root img, .life-kc-root svg, .life-kc-root table{max-width:100%}

/* ============================ layout */
.life-kc-root #shell{display:flex;min-height:100vh;width:100%}
/* Fixed desktop width: compact while keeping the main section headings readable. */
.life-kc-root #nav{width:245px;flex:0 0 245px;background:#082813;color:#C9DCD0;
 position:fixed;top:0;bottom:0;left:0;overflow-y:auto;overflow-x:hidden;z-index:120}
.life-kc-root #main{margin-left:245px;flex:1 1 auto;min-width:0;max-width:100%;padding:0 0 120px}
.life-kc-root .wrap{max-width:1120px;margin:0 auto;padding:0 clamp(20px,3vw,52px);width:100%}
.life-kc-root #scrim{display:none;position:fixed;inset:0;background:rgba(8,40,19,.55);z-index:110}
.life-kc-root #scrim.on{display:block}

/* ============================ NAV — dual tone hierarchy */
.life-kc-root .brand{padding:24px 22px 20px;border-bottom:1px solid rgba(255,255,255,.12);background:#082813}
.life-kc-root .brand-top{display:flex;align-items:center;gap:10px;min-width:0}
.life-kc-root .nav-home-back{
 display:inline-flex;
 align-items:center;
 justify-content:center;
 flex:0 0 28px;
 width:28px;
 height:28px;
 border:1px solid rgba(255,255,255,.24);
 border-radius:6px;
 background:rgba(255,255,255,.07);
 color:#FFFFFF;
 font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;
 font-size:18px;
 font-weight:500;
 line-height:1;
 text-decoration:none;
 cursor:pointer;
 transition:background .15s ease,border-color .15s ease,transform .15s ease
}
.life-kc-root .nav-home-back:hover{
 background:rgba(127,182,58,.18);
 border-color:#7FB63A;
 color:#FFFFFF;
 text-decoration:none;
 transform:translateX(-1px)
}
.life-kc-root .nav-home-back:focus-visible{
 outline:2px solid #7FB63A;
 outline-offset:2px
}

html body.life-kc-erpnext-page .life-kc-root #nav .brand .mark{font-family:Georgia,"Iowan Old Style","Times New Roman",serif;font-size:27px;letter-spacing:.2em;color:#fff;line-height:1;background:transparent;padding:0;margin:0;border:0;border-radius:0;box-shadow:none;display:block;width:auto;text-decoration:none}
.life-kc-root .brand .sub{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:9px;letter-spacing:.3em;text-transform:uppercase;color:#7FA189;margin-top:9px}
.life-kc-root .brand .kc{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:#7FB63A;margin-top:13px;font-weight:700}
.life-kc-root .searchbox{padding:15px 18px;border-bottom:1px solid rgba(255,255,255,.12);background:#0C3119}
.life-kc-root .searchbox input{width:100%;padding:11px 13px;border-radius:6px;border:1px solid rgba(255,255,255,.22);
 background:rgba(255,255,255,.08);color:#fff;font-size:14px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif}
.life-kc-root .searchbox input:focus{background:rgba(255,255,255,.14);border-color:#7FB63A}
.life-kc-root .searchbox input::placeholder{color:#7FA189}
.life-kc-root .searchbox .hint{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10px;color:#7A9885;margin-top:8px;letter-spacing:.04em;line-height:1.5}

/* MAIN MENU = rich tone */
.life-kc-root .navgroup{border-bottom:1px solid rgba(255,255,255,.08)}
.life-kc-root .navgroup>button{width:100%;text-align:left;background:#0C3119;border:0;border-left:3px solid transparent;
 color:#EAF3EC;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;
 padding:15px 15px 14px 17px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:10px;transition:.16s}
.life-kc-root .navgroup>button:hover{background:#154226;color:#fff}
.life-kc-root .navgroup>button .gr{display:flex;align-items:center;gap:9px;flex:0 0 auto}
.life-kc-root .navgroup>button .gc{display:none}
.life-kc-root .navgroup>button .chev{font-size:9px;color:#7FB63A;transition:transform .2s;display:inline-block}
/* OPEN state on a main menu */
.life-kc-root .navgroup.open>button{background:#1E5631;border-left-color:#7FB63A;color:#fff}
.life-kc-root .navgroup:not(.open)>button .chev{transform:rotate(-90deg)}
.life-kc-root .navgroup:not(.open) .navlist{display:none}

/* SUB MENU = lighter supporting tone */
.life-kc-root .navlist{padding:6px 0 12px;background:#154226;border-left:3px solid #1E5631}
.life-kc-root .navlist a{display:flex;align-items:baseline;padding:6px 14px 6px 17px;color:#BFD5C6;
 font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:14.2px;line-height:1.45;position:relative;transition:.14s}
.life-kc-root .navlist a:hover{color:#fff;background:rgba(255,255,255,.07);text-decoration:none}
.life-kc-root .navlist a .dot{flex:0 0 auto;width:5px;height:5px;border-radius:50%;border:1px solid #6E8E79;margin-right:11px;position:relative;top:-2px;transition:.14s}
.life-kc-root .navlist a .lb{flex:0 1 auto;min-width:0;max-width:74%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.life-kc-root .navlist a .ld{flex:1 1 auto;min-width:10px;border-bottom:1px dotted rgba(255,255,255,.24);margin:0 7px 4px}
.life-kc-root .navlist a .tg{flex:0 0 auto;font-size:10px;color:#8CAB97;letter-spacing:.05em}
/* ACTIVE item = strong accent tone */
.life-kc-root .navlist a.on{color:#fff;font-weight:600;background:linear-gradient(90deg,rgba(127,182,58,.22),rgba(127,182,58,.04))}
.life-kc-root .navlist a.on .dot{background:#7FB63A;border-color:#7FB63A;box-shadow:0 0 0 3px rgba(127,182,58,.28)}
.life-kc-root .navlist a.on .ld{border-bottom-color:rgba(127,182,58,.55)}
.life-kc-root .navlist a.on .tg{color:#A8D26A}
.life-kc-root .navlist a.on:before{content:"";position:absolute;left:0;top:3px;bottom:3px;width:3px;background:#7FB63A;border-radius:0 2px 2px 0}
.life-kc-root .navfoot{padding:18px 20px 34px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;color:#688A75;line-height:1.65;background:#082813}

/* ============================ page header — dual tone band */
.life-kc-root .page{display:none}
.life-kc-root .page.on{display:block}
.life-kc-root .phead{background:linear-gradient(180deg,#F4F9F5 0%,#fff 100%);
 border-bottom:1px solid #D5DED8;border-top:4px solid #1E5631;
 padding:clamp(20px,2.4vw,34px) 0 0;margin-bottom:clamp(22px,2.6vw,34px);position:relative}
.life-kc-root .backbar{padding-bottom:16px}
.life-kc-root .back{display:inline-flex;align-items:center;gap:8px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:12.5px;font-weight:600;
 letter-spacing:.05em;color:#1E5631;background:#fff;border:1px solid #C7DFCE;border-radius:6px;
 padding:8px 15px 8px 12px;cursor:pointer;transition:.15s;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04);max-width:100%}
.life-kc-root .back:hover{background:#1E5631;border-color:#1E5631;color:#fff;text-decoration:none;box-shadow:0 2px 6px rgba(12,49,25,.07), 0 4px 14px rgba(12,49,25,.05)}
.life-kc-root .back .ar{font-size:14px;line-height:1}
.life-kc-root .phead .top{display:flex;justify-content:space-between;align-items:flex-start;gap:clamp(16px,3vw,32px);flex-wrap:wrap}
.life-kc-root .phead .hl{flex:1 1 420px;min-width:0}
.life-kc-root .phead .eyebrow{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;letter-spacing:.24em;text-transform:uppercase;
 color:#1E5631;font-weight:700;margin-bottom:12px;display:flex;align-items:center;gap:9px;flex-wrap:wrap}
.life-kc-root .phead .eyebrow:before{content:"";width:22px;height:2px;background:#7FB63A;flex:0 0 auto}
.life-kc-root .phead h1{font-family:Georgia,"Iowan Old Style","Times New Roman",serif;font-size:clamp(28px,3.2vw,46px);line-height:1.08;font-weight:400;color:#12211A;letter-spacing:-.015em}
.life-kc-root .phead .aka{margin-top:13px;font-size:clamp(15px,1.1vw,18px);color:#68786E;max-width:44em;font-style:italic}
.life-kc-root .logo{width:clamp(140px,13vw,174px);height:auto;flex:0 0 auto;margin-top:2px}
.life-kc-root .meta{display:flex;flex-wrap:wrap;margin:24px 0 0;border-top:1px solid #E8EDE9;width:100%}
.life-kc-root .meta span{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:13px;color:#33443B;padding:11px 20px 13px 0;margin-right:20px;
 border-right:1px solid #E8EDE9;min-width:0}
.life-kc-root .meta span:last-child{border-right:0;margin-right:0}
.life-kc-root .meta span b{display:block;font-size:9.5px;letter-spacing:.16em;text-transform:uppercase;color:#68786E;font-weight:700;margin-bottom:3px}

/* ============================ typography */
.life-kc-root h2{font-family:Georgia,"Iowan Old Style","Times New Roman",serif;font-size:clamp(22px,2.1vw,30px);font-weight:400;color:#12211A;
 margin:clamp(34px,4vw,52px) 0 6px;letter-spacing:-.012em;line-height:1.2;display:flex;align-items:baseline;column-gap:14px;row-gap:0;flex-wrap:wrap}
.life-kc-root h2 .snum{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:11px;letter-spacing:.2em;color:#1E5631;font-weight:700;display:inline-flex;align-items:center;flex:0 0 auto;margin:0;line-height:1.2;white-space:nowrap}
.life-kc-root h2:after{content:"";display:block;width:58px;height:3px;background:linear-gradient(90deg,#1E5631,#7FB63A);margin-top:13px;border-radius:2px;flex:0 0 58px}
.life-kc-root h2:before{content:"";order:3;flex-basis:100%;height:0}
.life-kc-root h2:after{order:4}
.life-kc-root h2:first-child{margin-top:0}
.life-kc-root h3{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#1E5631;font-weight:700;margin:32px 0 12px}
.life-kc-root h4{font-family:Georgia,"Iowan Old Style","Times New Roman",serif;font-size:clamp(17px,1.3vw,20px);font-weight:400;color:#12211A;margin:24px 0 8px}
.life-kc-root p{margin-bottom:15px;max-width:38em}
.life-kc-root .lead{font-size:clamp(17px,1.3vw,20px);line-height:1.58;color:#12211A;max-width:36em;margin-bottom:20px}
.life-kc-root ul, .life-kc-root ol{margin:0 0 18px 0;max-width:40em}
.life-kc-root li{margin-bottom:7px}
.life-kc-root ul.plain{list-style:none}
.life-kc-root ul.plain>li{padding-left:22px;position:relative}
.life-kc-root ul.plain>li:before{content:"";position:absolute;left:2px;top:.7em;width:7px;height:7px;border-radius:50%;
 background:#E2EFE6;border:1.5px solid #2C6E3E}
.life-kc-root .rule{height:1px;background:#D5DED8;margin:40px 0;width:100%;max-width:100%}
.life-kc-root blockquote{border-left:3px solid #7FB63A;background:#F4F9F5;border-radius:0 6px 6px 0;
 padding:14px 20px;margin:22px 0;font-style:italic;color:#12211A;max-width:38em}

/* ============================ callouts — dual tone, semantic */
.life-kc-root .note, .life-kc-root .warn, .life-kc-root .danger{border-radius:10px;padding:16px 20px 17px;margin:22px 0;max-width:46em;
 font-size:clamp(15.5px,1.05vw,16.5px);border:1px solid;border-left-width:4px;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04)}
.life-kc-root .note{background:#EDF6EF;border-color:#BFDCC7;border-left-color:#2C6E3E}
.life-kc-root .warn{background:#FBF4E4;border-color:#E8D6A8;border-left-color:#9A6608;color:#5E4306}
.life-kc-root .danger{background:#FBEEEC;border-color:#EFC9C3;border-left-color:#A3271D;color:#6A1C15}
.life-kc-root .note b, .life-kc-root .warn b, .life-kc-root .danger b{display:block;margin-bottom:6px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;
 letter-spacing:.18em;text-transform:uppercase;font-weight:700}
.life-kc-root .note b{color:#2C6E3E} .life-kc-root .warn b{color:#9A6608} .life-kc-root .danger b{color:#A3271D}
.life-kc-root .note ul, .life-kc-root .warn ul, .life-kc-root .danger ul{margin:10px 0 0 20px;max-width:none}

/* ============================ eligibility split — dual tone panels */
.life-kc-root .split{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px;margin:24px 0;width:100%}
.life-kc-root .split>div{padding:20px 22px 22px;border-radius:10px;border:1px solid;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04);min-width:0}
.life-kc-root .split .go{background:#EDF6EF;border-color:#BFDCC7}
.life-kc-root .split .no{background:#FBEEEC;border-color:#EFC9C3}
.life-kc-root .split h4{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;
 margin:0 0 14px;padding-bottom:11px;border-bottom:2px solid;display:flex;align-items:center;gap:9px}
.life-kc-root .split .go h4{color:#2C6E3E;border-color:#BFDCC7}
.life-kc-root .split .no h4{color:#A3271D;border-color:#EFC9C3}
.life-kc-root .split h4 .ic{width:20px;height:20px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;
 font-size:11px;color:#fff;flex:0 0 auto}
.life-kc-root .split .go h4 .ic{background:#2C6E3E} .life-kc-root .split .no h4 .ic{background:#A3271D}
.life-kc-root .split ul{list-style:none;max-width:none;margin:0}
.life-kc-root .split li{padding:7px 0 7px 24px;position:relative;font-size:clamp(15px,1vw,16px);line-height:1.55;border-bottom:1px solid rgba(0,0,0,.05)}
.life-kc-root .split li:last-child{border-bottom:0}
.life-kc-root .split .go li:before{content:"✓";position:absolute;left:0;color:#2C6E3E;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:13px;font-weight:700}
.life-kc-root .split .no li:before{content:"✕";position:absolute;left:0;color:#A3271D;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:13px;font-weight:700}
.life-kc-root .split .kv{font-weight:700;color:#12211A}

/* ============================ tables — rich header, light body */
.life-kc-root .tw{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:20px 0;width:100%;max-width:100%;
 border:1px solid #D5DED8;border-radius:10px;background:#fff;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04)}
.life-kc-root table{width:100%;border-collapse:collapse;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:clamp(13.5px,.95vw,14.8px);min-width:520px}
.life-kc-root caption{caption-side:top;text-align:left;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;letter-spacing:.18em;
 text-transform:uppercase;color:#1E5631;font-weight:700;padding:14px 18px 12px;background:#F4F9F5;
 border-bottom:1px solid #E8EDE9}
.life-kc-root th{text-align:left;padding:12px 16px;font-size:11px;letter-spacing:.13em;text-transform:uppercase;font-weight:700;
 vertical-align:bottom;color:#fff;background:#1E5631;border-bottom:2px solid #154226}
.life-kc-root th:first-child{padding-left:18px}
.life-kc-root td{padding:11px 16px;border-bottom:1px solid #E8EDE9;vertical-align:top;line-height:1.55;color:#33443B}
.life-kc-root td:first-child{padding-left:18px}
.life-kc-root tbody tr:nth-child(even){background:#FAFCFA}
.life-kc-root tbody tr:hover{background:#EDF5EF}
.life-kc-root tbody tr:last-child td{border-bottom:0}
.life-kc-root td b{color:#12211A;font-weight:700}
.life-kc-root td.x, .life-kc-root td.tri, .life-kc-root td.dash{text-align:center;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;white-space:nowrap}
.life-kc-root td.x{color:#A3271D;font-weight:700}
.life-kc-root td.tri{color:#9A6608;font-weight:700}
.life-kc-root td.dash{color:#93A199}
.life-kc-root tr.sub td{background:#E2EFE6;border-bottom:1px solid #C7DFCE;padding-top:12px;padding-bottom:12px}
.life-kc-root tr.sub td b{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:10.5px;letter-spacing:.18em;text-transform:uppercase;color:#154226}

/* ============================ protocol steps */
.life-kc-root .steps{margin:22px 0;border:1px solid #D5DED8;border-radius:10px;overflow:hidden;background:#fff;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04)}
.life-kc-root .step{display:flex;gap:18px;padding:15px 20px;border-bottom:1px solid #E8EDE9;min-width:0}
.life-kc-root .step:nth-child(even){background:#FAFCFA}
.life-kc-root .step:last-child{border-bottom:0}
.life-kc-root .step .n{flex:0 0 46px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:11px;font-weight:700;color:#fff;background:#2C6E3E;
 letter-spacing:.06em;height:26px;border-radius:13px;display:flex;align-items:center;justify-content:center;margin-top:2px}
.life-kc-root .step .b{flex:1 1 auto;min-width:0}
.life-kc-root .step .t{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-weight:700;color:#12211A;font-size:15px;margin-bottom:4px}
.life-kc-root .step .d{font-size:clamp(15.5px,1.05vw,16.5px);max-width:44em}

/* ============================ do / don't */
.life-kc-root .dd{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:18px;margin:22px 0;width:100%}
.life-kc-root .dd>div{padding:20px 22px 22px;border-radius:10px;border:1px solid;box-shadow:0 1px 2px rgba(12,49,25,.06), 0 1px 1px rgba(12,49,25,.04);min-width:0}
.life-kc-root .dd .do{background:#EDF6EF;border-color:#BFDCC7}
.life-kc-root .dd .dont{background:#FBEEEC;border-color:#EFC9C3}
.life-kc-root .dd h4{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;font-size:11px;letter-spacing:.18em;text-transform:uppercase;font-weight:700;
 margin:0 0 13px;padding-bottom:11px;border-bottom:2px solid}
.life-kc-root .dd .do h4{color:#2C6E3E;border-color:#BFDCC7}
