/* ============================================================
   FIX — Seven-step client journey connector
   Keep the dotted line BETWEEN circles, never through 1–7.
   ============================================================ */
.life-kc-root svg[aria-label="Seven-step client journey"] circle{
  fill:#fff;
}

/* ============================================================
   KNOWLEDGE CENTRE — DESKTOP SIDEBAR CLOSE / OPEN
   ============================================================ */

.life-kc-root .kc-sidebar-tools {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  padding: 10px 12px 4px;
  background: #082813;
}

/* Close button inside sidebar */
.life-kc-root .kc-side-close {
  width: 30px;
  height: 30px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255,255,255,.22);
  border-radius: 7px;

  background: rgba(255,255,255,.08);
  color: #fff;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 20px;
  font-weight: 500;
  line-height: 1;

  cursor: pointer;

  transition:
    background .15s ease,
    border-color .15s ease,
    transform .15s ease;
}

.life-kc-root .kc-side-close:hover {
  background: rgba(255,255,255,.16);
  border-color: #7FB63A;
  transform: scale(1.04);
}


/* Floating reopen button */
.life-kc-root .kc-side-open {
  display: none;

  position: fixed;
  left: 12px;
  top: 14px;
  z-index: 150;

  width: 38px;
  height: 38px;

  align-items: center;
  justify-content: center;

  border: 1px solid rgba(255,255,255,.25);
  border-radius: 8px;

  background: #0C3119;
  color: #fff;

  font-size: 17px;
  line-height: 1;

  cursor: pointer;

  box-shadow: 0 4px 14px rgba(8,40,19,.22);
}

.life-kc-root .kc-side-open:hover {
  background: #1E5631;
}


/* DESKTOP ONLY */
@media (min-width: 901px) {

  /* Fixed compact sidebar width. Search no longer changes the layout width. */
  .life-kc-root #nav {
    transition: transform .22s ease;
  }

  /* Slide sidebar away */
  .life-kc-root #nav.kc-collapsed {
    transform: translateX(-100%);
  }

  /* Main content uses full width */
  .life-kc-root.kc-sidebar-closed #main {
    margin-left: 0;
    width: 100%;
  }

  /* Show reopen button only while sidebar is closed */
  .life-kc-root.kc-sidebar-closed .kc-side-open {
    display: inline-flex;
  }
}


/* MOBILE:
   existing mobile hamburger already handles sidebar */
@media (max-width: 900px) {

  .life-kc-root .kc-sidebar-tools {
    padding: 8px 10px 3px;
  }

  .life-kc-root .kc-side-open {
    display: none !important;
  }
}


#life-kc-root .logo{
    display:none !important;
}

