(function(){
 "use strict";
 function lifeKCInit(){
 var root=document.getElementById('life-kc-root');
 if(!root || root.getAttribute('data-life-kc-ready')==='1') return;
 root.setAttribute('data-life-kc-ready','1');
 document.body.classList.add('life-kc-erpnext-page');
 var pages   = [].slice.call(root.querySelectorAll('.page'));
 var links   = [].slice.call(root.querySelectorAll('.navlist a[data-p]'));
 var groups  = [].slice.call(root.querySelectorAll('.navgroup'));
 var navEl   = root.querySelector('#nav');
 var scrim   = root.querySelector('#scrim');
 var cur     = null;
 var stack   = [];          /* real visit history, for the Back button */
 var goingBack = false;

 /* ---------------- toast ---------------- */
 var toastEl=null, toastT=null;
 function toast(msg){
  if(!toastEl){toastEl=document.createElement('div');toastEl.className='toast';root.appendChild(toastEl);}
  toastEl.textContent=msg;
  toastEl.classList.add('on');
  clearTimeout(toastT);
  toastT=setTimeout(function(){toastEl.classList.remove('on');},2600);
 }
 window.__toast=toast;

 /* ---------------- menu: accordion, one open at a time ---------------- */
 function openGroup(g){
  groups.forEach(function(x){ x.classList.toggle('open', x===g); });
 }
 groups.forEach(function(g){
  var b=g.querySelector('button');
  b.setAttribute('aria-expanded', g.classList.contains('open')?'true':'false');
  b.addEventListener('click',function(){
   var wasOpen=g.classList.contains('open');
   groups.forEach(function(x){
     x.classList.remove('open');
     var bb=x.querySelector('button'); if(bb) bb.setAttribute('aria-expanded','false');
   });
   if(!wasOpen){ g.classList.add('open'); b.setAttribute('aria-expanded','true'); }
  });
 });

 function closeNav(){ navEl.classList.remove('open'); if(scrim) scrim.classList.remove('on'); }
 function openNav(){ navEl.classList.add('open'); if(scrim) scrim.classList.add('on'); }

 /* =========================================================
   DESKTOP SIDEBAR CLOSE / OPEN
   ========================================================= */

var kcSideClose = root.querySelector('#kcSideClose');
var kcSideOpen  = root.querySelector('#kcSideOpen');

function closeKnowledgeSidebar() {

  /* Mobile already has its own drawer behaviour */
  if (window.innerWidth <= 900) {
    closeNav();
    return;
  }

  navEl.classList.add('kc-collapsed');
  root.classList.add('kc-sidebar-closed');
}

function openKnowledgeSidebar() {

  if (window.innerWidth <= 900) {
    openNav();
    return;
  }

  navEl.classList.remove('kc-collapsed');
  root.classList.remove('kc-sidebar-closed');
}

if (kcSideClose) {
  kcSideClose.addEventListener(
    'click',
    closeKnowledgeSidebar
  );
}

if (kcSideOpen) {
  kcSideOpen.addEventListener(
    'click',
    openKnowledgeSidebar
  );
}



 /* ---------------- routing ---------------- */
 function show(id){
  if(id===cur){ updateBack(id); return; }   /* already here — nothing to redraw */
  var found=false;
  pages.forEach(function(p){var on=(p.id===id);p.classList.toggle('on',on);if(on)found=true;});
  if(!found){ root.querySelector('#home').classList.add('on'); id='home'; }

  /* maintain the visit stack so Back returns to where you actually came from */
  if(!goingBack && cur!==null && id!==cur){ stack.push(cur); if(stack.length>60) stack.shift(); }
  goingBack=false;
  cur=id;

  links.forEach(function(a){a.classList.toggle('on',a.getAttribute('data-p')===id);});
  var act=root.querySelector('.navlist a.on');
  if(act){
   var g=act.parentNode.parentNode;
   if(g && g.classList.contains('navgroup')) openGroup(g);
   try{ act.scrollIntoView({block:'nearest'}); }catch(e){}
  }
  var s=root.querySelector('#sr'); if(s) s.classList.remove('on');
  var q=root.querySelector('#q'); if(q) q.value='';
  updateBack(id);
  window.scrollTo(0,0);
  if(window.innerWidth<=900) closeNav();
 }

 /* ---------------- back button ---------------- */
 function labelFor(id){
  var a=root.querySelector('.navlist a[data-p="'+id+'"] .lb');
  if(a) return a.textContent.trim();
  return 'Home';
 }
 function updateBack(id){
  var page=root.querySelector('#'+CSS.escape(id)); if(!page) return;
  var btn=page.querySelector('.back'); if(!btn) return;
  var prev = stack.length ? stack[stack.length-1] : null;
  var target, text;
  if(prev && prev!==id){ target=prev; text='Back to '+labelFor(prev); }
  else { target=btn.getAttribute('data-parent')||'home'; text='Back to '+labelFor(target); }
  btn.setAttribute('data-target',target);
  var lbl=btn.querySelector('.bl'); if(lbl) lbl.textContent=text;
 }
 document.addEventListener('click',function(ev){
  var b=ev.target.closest ? ev.target.closest('.back') : null;
  if(!b || !root.contains(b)) return;
  ev.preventDefault();
  var t=b.getAttribute('data-target')||b.getAttribute('data-parent')||'home';
  if(stack.length && stack[stack.length-1]===t){ stack.pop(); goingBack=true; }
  try{ location.hash='#'+t; }catch(e){}
  show(t);                       /* navigate now; the later hashchange is a no-op */
 });

 function route(){ show((location.hash||'#home').slice(1)); }
 window.addEventListener('hashchange',route);

 var mb=root.querySelector('#mb');
 if(mb) mb.addEventListener('click',function(){
   if(navEl.classList.contains('open')) closeNav(); else openNav();
 });
 if(scrim) scrim.addEventListener('click',closeNav);
 document.addEventListener('keydown',function(e){
   if(e.key==='Escape'){ closeNav(); }
   if(e.key==='/' && (!document.activeElement || document.activeElement.tagName!=='INPUT')){ e.preventDefault(); var q=root.querySelector('#q'); if(q) q.focus(); }
 });

 /* ---------------- search ---------------- */
 var IDX=window.__IDX__||[];
 var q=root.querySelector('#q'), sr=root.querySelector('#sr'),
     srb=root.querySelector('#srb'), srh=root.querySelector('#srh'),
     flt=root.querySelector('#flt');
 var scope='all';

 /* Show the complete sidebar item name on mouse hover.
    Native title tooltips are used so they are not clipped by the scrollable sidebar. */
 links.forEach(function(a){
  var lb=a.querySelector('.lb');
  if(!lb)return;
