   if(!ok)continue;
   if(it.t.toLowerCase().indexOf(v.toLowerCase())>-1)sc+=5;
   if(it.t.toLowerCase().indexOf(terms[0])===0)sc+=3;
   res.push({it:it,sc:sc});
  }
  res.sort(function(a,b){return b.sc-a.sc||a.it.t.localeCompare(b.it.t)});
  var cap=terms.length?60:400, shown=res.slice(0,cap);
