    : ('Browsing everything &mdash; '+res.length+' entries. Type to narrow it down.');
  srb.innerHTML=shown.map(function(r){
   var snip=r.it.k.length>190?r.it.k.slice(0,190)+'\u2026':r.it.k;
   return '<a class="ixc" href="#'+r.it.p+'"><div class="n">'+hl(r.it.t,terms)+'</div>'+
          '<div class="m">'+hl(snip,terms)+'</div><div class="tags"><i>'+esc(r.it.s)+'</i></div></a>';
  }).join('');
  if(res.length>cap)srb.innerHTML+='<div class="ixc"><div class="m">Showing the first '+cap+'. Keep typing to narrow the list.</div></div>';
 }
 function openSearch(){pages.forEach(function(p){p.classList.remove('on');});sr.classList.add('on');}
