 /* ---------------- print a single document ---------------- */
 window.printOnly=function(id){
  var el=root.querySelector('#'+CSS.escape(id));
  if(!el){toast('Document not found.');return;}
  var host=document.createElement('div');
  host.className='page on printonly'; host.id='__pr__';
  host.innerHTML='<div class="wrap">'+el.innerHTML+'</div>';
  var prev=[].slice.call(root.querySelectorAll('.page.on'));
  prev.forEach(function(p){p.classList.remove('on');});
  root.querySelector('#main').appendChild(host);
  window.print();
  setTimeout(function(){
   if(host.parentNode)host.parentNode.removeChild(host);
   prev.forEach(function(p){p.classList.add('on');});
  },600);
 };

