 /* ---------------- SHARE — works offline, shares real content ---------------- */
 function plainText(el){
  var c=el.cloneNode(true);
  [].slice.call(c.querySelectorAll('svg,.btnbar,.btn,.back,script')).forEach(function(n){n.remove();});
  [].slice.call(c.querySelectorAll('h1,h2,h3,h4,.dt,.ht,.t,li,tr,p,div.line')).forEach(function(n){
    n.insertAdjacentText('afterend','\n');
  });
  var t=(c.innerText||c.textContent||'');
  return t.replace(/[ \t]+/g,' ').replace(/\n{3,}/g,'\n\n').trim();
 }
 window.shareDoc=function(title,id){
  var el = id ? root.querySelector('#'+CSS.escape(id)) : root.querySelector('.page.on');
  if(!el){toast('Nothing to share on this screen.');return;}
  var text = plainText(el);
  var head = 'LIFE SLIMMING AND COSMETIC CLINIC PVT. LTD.\n' + title + '\n' +
             '\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\u2014\n';
  var payload = head + text;
  var file = null;
  /* 1. native share with a file, where supported */
  try{
   if(navigator.canShare && window.File){
    file = new File([payload], (title.replace(/[^\w\s-]/g,'').trim().replace(/\s+/g,'_')||'LIFE_document')+'.txt', {type:'text/plain'});
    if(navigator.canShare({files:[file]})){
     navigator.share({title:title, text:'LIFE Knowledge Centre \u2014 '+title, files:[file]})
      .then(function(){toast('Shared.');})
      .catch(function(e){ if(e && e.name!=='AbortError') fallbackShare(title,payload); });
     return;
    }
   }
  }catch(e){}
  /* 2. native share with text */
  try{
   if(navigator.share){
    navigator.share({title:title, text:payload.slice(0,4000)})
     .then(function(){toast('Shared.');})
     .catch(function(e){ if(e && e.name!=='AbortError') fallbackShare(title,payload); });
    return;
   }
  }catch(e){}
  fallbackShare(title,payload);
 };
 function fallbackShare(title,payload){
  /* 3. copy the actual content to the clipboard */
  if(navigator.clipboard && navigator.clipboard.writeText){
   navigator.clipboard.writeText(payload).then(
     function(){toast(title+' copied to clipboard \u2014 paste it into WhatsApp or email.');},
     function(){legacyCopy(title,payload);});
   return;
  }
  legacyCopy(title,payload);
 }
 function legacyCopy(title,payload){
  try{
   var ta=document.createElement('textarea');
   ta.value=payload;
   ta.style.position='fixed'; ta.style.top='-1000px';
   document.body.appendChild(ta); ta.select();
   var ok=document.execCommand('copy');
   document.body.removeChild(ta);
   toast(ok ? (title+' copied to clipboard.') : 'Copy failed \u2014 use Download as Word instead.');
  }catch(e){ toast('Copy failed \u2014 use Download as Word instead.'); }
 }

